  "ISRIC SoilGrids topsoil (0-30 cm); scored softly against each species' EcoCrop texture preference": "Suelo superficial ISRIC SoilGrids (0-30 cm); puntuado suavemente contra la preferencia de textura EcoCrop de cada especie",
  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "El suelo superficial medido aquí es {t}, fuera del rango de textura preferido de esta especie: penalización suave, nunca exclusión.",
  "irrigated": "con riego",
  "measured pH": "pH medido",
  "measured": "medido",
  "Scored as irrigated: water counts as available up to this species' optimum. Excess rain still applies.": "Puntuado con riego: el agua cuenta como disponible hasta el óptimo de esta especie. El exceso de lluvia sigue aplicando.",
  "Annual rain here sits just above this species' EcoCrop ceiling. Excess-rain limits proxy disease and drainage rather than survival, so it takes a half penalty instead of exclusion.": "La lluvia anual aquí queda apenas por encima del techo EcoCrop de esta especie. Los límites por exceso de lluvia reflejan enfermedad y drenaje, no supervivencia, así que recibe media penalización en vez de exclusión.",
  "wetland": "humedal",
  "on slope": "en pendiente",
  "Needs standing water or saturated soil year-round (EcoCrop drainage)": "Necesita agua estancada o suelo saturado todo el año (drenaje EcoCrop)",
  "This is a wetland species (needs saturated soil or standing water), and this point sits on a {n}° slope.": "Es una especie de humedal (necesita suelo saturado o agua estancada), y este punto está en una pendiente de {n}°.",
  "Requires at least {req} cm soil depth (EcoCrop), but this {slope}° slope supports only ~{avail} cm equilibrium soil.": "Requiere al menos {req} cm de profundidad de suelo (EcoCrop), pero esta pendiente de {slope}° solo admite ~{avail} cm de suelo en equilibrio.",
