  "Public land? You can plant, just tell the city first and follow the local urban forestry plan. Private land? Talk to the owner before anything.": "Terrain public ? Vous pouvez planter, prévenez d'abord la mairie et suivez le plan local de végétalisation. Terrain privé ? Parlez au propriétaire avant tout.",
