  "native · other region": "indigène · autre région",
  "Native to this country, but not to this region (WCVP)": "Indigène de ce pays, mais pas de cette région (WCVP)",
  "Part of the native flora of this region (WCVP)": "Fait partie de la flore indigène de cette région (WCVP)",
  "{n} species recorded as invasive in this country were excluded from these recommendations ({src}).": "{n} espèces recensées comme envahissantes dans ce pays ont été exclues de ces recommandations ({src}).",
  "No natives from our base clear the bar here. The base (FAO EcoCrop) covers cultivated species and thinly covers wild native floras, like this region's; try 'everything', or ask a local restoration nursery.": "Aucune indigène de notre base ne passe le seuil ici. La base (FAO EcoCrop) couvre des espèces cultivées et représente mal les flores sauvages, comme celle de cette région ; essayez « tout » ou une pépinière locale de restauration.",
  "The record low here sits within the grid's frost margin. Reanalysis under-reports valley and highland night frosts, so this frost-tender species takes a half penalty.": "Le minimum record ici tombe dans la marge de gel de la grille. La réanalyse sous-estime les gelées nocturnes de vallée et d'altitude ; cette espèce sensible au gel prend une demi-pénalité.",
  "Part of the native flora of {region} (WCVP). Ranges resolve at whole-province scale; where a species grows within {region} varies.": "Fait partie de la flore indigène de {region} (WCVP). Les aires se résolvent à l'échelle de la province entière ; la présence locale dans {region} varie.",
  "Inside this species' mapped native range (Little/USGS digitized polygons, ~50 km resolution)": "Dans l'aire indigène cartographiée de cette espèce (polygones numérisés Little/USGS, résolution ~50 km)",
  "Native to this country, but its mapped range (Little/USGS) does not reach here": "Indigène de ce pays, mais son aire cartographiée (Little/USGS) n'atteint pas cet endroit",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native right here per its mapped range. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop indique une température létale au-dessus du minimum record de ce site, mais l'espèce est indigène ici même selon son aire cartographiée. Demi-pénalité au lieu d'une exclusion ; le champ de rusticité est le suspect.",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native to this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop indique une température létale au-dessus du minimum record de ce site, mais l'espèce est indigène de ce pays. Demi-pénalité au lieu d'une exclusion ; le champ de rusticité est le suspect.",
  "EcoCrop lists a killing temperature above this site's record low, but Kew records the species as naturalized in this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop indique une température létale au-dessus du minimum record de ce site, mais Kew enregistre l'espèce comme naturalisée dans ce pays. Demi-pénalité au lieu d'une exclusion ; le champ de rusticité est le suspect.",
  "soil texture": "texture du sol",
  "light (sandy)": "légère (sableuse)",
  "medium (loamy)": "moyenne (limoneuse)",
  "heavy (clayey)": "lourde (argileuse)",
  "organic (peaty)": "organique (tourbeuse)",
  "ISRIC SoilGrids topsoil (0-30 cm); scored softly against each species' EcoCrop texture preference": "Sol superficiel ISRIC SoilGrids (0-30 cm) ; noté doucement contre la préférence de texture EcoCrop de chaque espèce",
  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "Le sol superficiel mesuré ici est {t}, hors de la gamme de texture préférée de cette espèce : pénalité douce, jamais une exclusion.",
  "irrigated": "irrigué",
  "measured pH": "pH mesuré",
  "measured": "mesuré",
  "Scored as irrigated: water counts as available up to this species' optimum. Excess rain still applies.": "Noté comme irrigué : l'eau compte comme disponible jusqu'à l'optimum de l'espèce. L'excès de pluie s'applique toujours.",
  "Annual rain here sits just above this species' EcoCrop ceiling. Excess-rain limits proxy disease and drainage rather than survival, so it takes a half penalty instead of exclusion.": "Les pluies annuelles ici dépassent à peine le plafond EcoCrop de cette espèce. Les limites d'excès de pluie reflètent maladies et drainage, pas la survie ; demi-pénalité au lieu d'une exclusion.",
  "wetland": "zone humide",
  "on slope": "sur pente",
  "Needs standing water or saturated soil year-round (EcoCrop drainage)": "A besoin d'eau stagnante ou de sol saturé toute l'année (drainage EcoCrop)",
  "This is a wetland species (needs saturated soil or standing water), and this point sits on a {n}° slope.": "C'est une espèce de zone humide (sol saturé ou eau stagnante requis), et ce point se trouve sur une pente de {n}°.",
  "Requires at least {req} cm soil depth (EcoCrop), but this {slope}° slope supports only ~{avail} cm equilibrium soil.": "Nécessite au moins {req} cm de profondeur de sol (EcoCrop), mais cette pente de {slope}° ne permet que ~{avail} cm de sol à l'équilibre.",
  "Did something look wrong? Send feedback": "Quelque chose cloche ? Envoyez un retour",
