  "Nursery-raised seedlings ensure early survival against weed competition and surface desiccation; mean field establishment from direct seeding is only ~11% (Ceccon et al. 2016).": "苗圃培育的苗木（容器苗或裸根苗）能有效抵御杂草竞争与地表干燥，确保初期存活率。直播田间平均成苗率仅约11%（Ceccon等2016）。",
