  "Native to this country, but not to this region (WCVP)": "この国の在来種ですが、この地域には自生しません（WCVP）",
  "Part of the native flora of this region (WCVP)": "この地域の在来植物相の一部（WCVP）",
  "{n} species recorded as invasive in this country were excluded from these recommendations ({src}).": "この国で侵略的と記録されている{n}種を推奨から除外しました（{src}）。",
  "No natives from our base clear the bar here. The base (FAO EcoCrop) covers cultivated species and thinly covers wild native floras, like this region's; try 'everything', or ask a local restoration nursery.": "当データベースの在来種でここの基準を満たすものはありません。ベース（FAO EcoCrop）は栽培種中心で、この地域のような野生の在来植物相の収録は薄いです。「すべて」を試すか、地元の再生苗木店にご相談を。",
  "The record low here sits within the grid's frost margin. Reanalysis under-reports valley and highland night frosts, so this frost-tender species takes a half penalty.": "ここの過去最低気温はグリッドの霜マージン内にあります。再解析データは谷間や高地の夜間霜を過小評価するため、この霜に弱い種は半分のペナルティを受けます。",
  "Part of the native flora of {region} (WCVP). Ranges resolve at whole-province scale; where a species grows within {region} varies.": "{region}の在来植物相の一部（WCVP）。分布は州・省全体の解像度で、{region}内のどこに生えるかは場所により異なります。",
  "Inside this species' mapped native range (Little/USGS digitized polygons, ~50 km resolution)": "この種の地図化された自生域の内側です（Little/USGSデジタル化ポリゴン、解像度約50 km）",
  "Native to this country, but its mapped range (Little/USGS) does not reach here": "この国の在来種ですが、地図化された分布域（Little/USGS）はここまで届いていません",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native right here per its mapped range. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCropの致死温度はこの地点の過去最低気温より高いですが、この種は地図化された分布によればまさにここの在来種です。除外ではなく半減点とし、耐寒性フィールドを疑っています。",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native to this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCropの致死温度はこの地点の過去最低気温より高いですが、この種はこの国の在来種です。除外ではなく半減点とし、耐寒性フィールドを疑っています。",
  "EcoCrop lists a killing temperature above this site's record low, but Kew records the species as naturalized in this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCropの致死温度はこの地点の過去最低気温より高いですが、Kewはこの種をこの国で帰化していると記録しています。除外ではなく半減点とし、耐寒性フィールドを疑っています。",
  "soil texture": "土性",
  "light (sandy)": "軽い（砂質）",
  "medium (loamy)": "中間（壌土質）",
  "heavy (clayey)": "重い（粘土質）",
  "organic (peaty)": "有機質（泥炭質）",
  "ISRIC SoilGrids topsoil (0-30 cm); scored softly against each species' EcoCrop texture preference": "ISRIC SoilGrids 表土（0-30 cm）。各種のEcoCrop土性選好に対してソフトに採点されます",
  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "この地点の実測表土は{t}で、この種の好む土性範囲外です。ソフトな減点で、除外にはなりません。",
  "irrigated": "灌漑あり",
  "measured pH": "実測pH",
  "measured": "実測",
  "Scored as irrigated: water counts as available up to this species' optimum. Excess rain still applies.": "灌漑ありとして採点：水はこの種の最適域まで利用可能として扱います。過剰な雨の制限は引き続き適用されます。",
  "Annual rain here sits just above this species' EcoCrop ceiling. Excess-rain limits proxy disease and drainage rather than survival, so it takes a half penalty instead of exclusion.": "この地点の年間降水量はこの種のEcoCrop上限をわずかに上回ります。過剰降水の制限は生存ではなく病害と排水の代理指標のため、除外ではなく半減点とします。",
  "wetland": "湿地",
  "on slope": "斜面上",
  "Needs standing water or saturated soil year-round (EcoCrop drainage)": "一年中、滞水または飽和した土壌が必要です（EcoCrop排水特性）",
  "This is a wetland species (needs saturated soil or standing water), and this point sits on a {n}° slope.": "これは湿地性の種（飽和土壌または滞水が必要）ですが、この地点は{n}°の斜面にあります。",
  "Requires at least {req} cm soil depth (EcoCrop), but this {slope}° slope supports only ~{avail} cm equilibrium soil.": "最低 {req} cmの土壌深度が必要ですが（EcoCrop）、この {slope}° の斜面では約 {avail} cmの平衡土壌しか維持できません。",
  "Did something look wrong? Send feedback": "何かおかしい？フィードバックを送る",
