  "Native to this country, but not to this region (WCVP)": "Местный для страны, но не для этого региона (WCVP)",
  "Part of the native flora of this region (WCVP)": "Часть местной флоры этого региона (WCVP)",
  "{n} species recorded as invasive in this country were excluded from these recommendations ({src}).": "{n} видов, отмеченных как инвазивные в этой стране, исключены из рекомендаций ({src}).",
  "No natives from our base clear the bar here. The base (FAO EcoCrop) covers cultivated species and thinly covers wild native floras, like this region's; try 'everything', or ask a local restoration nursery.": "Ни один местный вид из нашей базы здесь не проходит порог. База (FAO EcoCrop) охватывает культурные виды и слабо покрывает дикие местные флоры, как здешняя; попробуйте «всё» или спросите в местном питомнике восстановления.",
  "The record low here sits within the grid's frost margin. Reanalysis under-reports valley and highland night frosts, so this frost-tender species takes a half penalty.": "Рекордный минимум здесь попадает в запас на заморозки для ячейки сетки. Реанализ занижает ночные заморозки долин и высокогорий, поэтому этот неморозостойкий вид получает половинный штраф.",
  "Part of the native flora of {region} (WCVP). Ranges resolve at whole-province scale; where a species grows within {region} varies.": "Часть местной флоры региона {region} (WCVP). Ареалы разрешаются на уровне целой провинции; где именно вид растёт в пределах {region}, различается.",
  "Inside this species' mapped native range (Little/USGS digitized polygons, ~50 km resolution)": "Внутри картированного естественного ареала этого вида (оцифрованные полигоны Little/USGS, разрешение ~50 км)",
  "Native to this country, but its mapped range (Little/USGS) does not reach here": "Местный для страны вид, но его картированный ареал (Little/USGS) сюда не доходит",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native right here per its mapped range. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop указывает губительную температуру выше рекордного минимума этого места, но по картированному ареалу вид здесь местный. Половинный штраф вместо исключения; поле морозостойкости под подозрением.",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native to this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop указывает губительную температуру выше рекордного минимума этого места, но вид является местным для этой страны. Половинный штраф вместо исключения; поле морозостойкости под подозрением.",
  "EcoCrop lists a killing temperature above this site's record low, but Kew records the species as naturalized in this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop указывает губительную температуру выше рекордного минимума этого места, но Kew отмечает вид как натурализованный в этой стране. Половинный штраф вместо исключения; поле морозостойкости под подозрением.",
  "soil texture": "текстура почвы",
  "light (sandy)": "лёгкая (песчаная)",
  "medium (loamy)": "средняя (суглинистая)",
  "heavy (clayey)": "тяжёлая (глинистая)",
  "organic (peaty)": "органическая (торфяная)",
  "ISRIC SoilGrids topsoil (0-30 cm); scored softly against each species' EcoCrop texture preference": "Верхний слой почвы ISRIC SoilGrids (0-30 см); мягко оценивается относительно предпочтений текстуры EcoCrop каждого вида",
  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "Измеренный верхний слой почвы здесь {t}, вне предпочтительного диапазона текстуры этого вида: мягкий штраф, никогда не исключение.",
  "irrigated": "орошается",
  "measured pH": "измеренный pH",
  "measured": "измерено",
  "Scored as irrigated: water counts as available up to this species' optimum. Excess rain still applies.": "Оценка с орошением: вода считается доступной до оптимума вида. Избыток осадков по-прежнему учитывается.",
  "Annual rain here sits just above this species' EcoCrop ceiling. Excess-rain limits proxy disease and drainage rather than survival, so it takes a half penalty instead of exclusion.": "Годовые осадки здесь чуть выше потолка EcoCrop для этого вида. Пределы избытка осадков отражают болезни и дренаж, а не выживание, поэтому половинный штраф вместо исключения.",
  "wetland": "водно-болотный",
  "on slope": "на склоне",
  "Needs standing water or saturated soil year-round (EcoCrop drainage)": "Нужна стоячая вода или насыщенная влагой почва круглый год (дренаж EcoCrop)",
  "This is a wetland species (needs saturated soil or standing water), and this point sits on a {n}° slope.": "Это водно-болотный вид (нужна насыщенная почва или стоячая вода), а эта точка находится на склоне {n}°.",
  "Requires at least {req} cm soil depth (EcoCrop), but this {slope}° slope supports only ~{avail} cm equilibrium soil.": "Требуется глубина почвы не менее {req} см (EcoCrop), но этот склон {slope}° удерживает лишь ~{avail} см равновесной почвы.",
  "Did something look wrong? Send feedback": "Что-то не так? Отправьте отзыв",
  "What was wrong, or what was missing?": "Что было не так или чего не хватало?",
