  "EcoCrop lists a killing temperature above this site's record low, but the species is native right here per its mapped range. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop mencantumkan suhu mematikan di atas rekor terendah situs ini, tetapi spesies ini asli tepat di sini menurut sebaran terpetakannya. Penalti setengah alih-alih dikecualikan; kolom ketahanan dingin yang dicurigai.",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native to this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop mencantumkan suhu mematikan di atas rekor terendah situs ini, tetapi spesies ini asli negara ini. Penalti setengah alih-alih dikecualikan; kolom ketahanan dingin yang dicurigai.",
  "EcoCrop lists a killing temperature above this site's record low, but Kew records the species as naturalized in this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop mencantumkan suhu mematikan di atas rekor terendah situs ini, tetapi Kew mencatat spesies ini ternaturalisasi di negara ini. Penalti setengah alih-alih dikecualikan; kolom ketahanan dingin yang dicurigai.",
