  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "Tanah lapisan atas terukur di sini {t}, di luar rentang tekstur yang disukai spesies ini: penalti lunak, tidak pernah pengecualian.",
