  "Plots for this area: {n} of 100 m2 (25 x 4 m). A regenerant counts from 50 cm height with CAP under 15 cm.": "इस क्षेत्र के लिए प्लॉट: 100 m2 के {n} (25 x 4 m)। अपने आप उगा पौधा (रीजेनरेंट) 50 cm ऊँचाई से गिना जाता है, बशर्ते CAP 15 cm से कम हो।",
  "Anexo III suggests at least 80 regional native species for full-area planting. It is guidance, not a requirement.": "Anexo III पूरे क्षेत्र में रोपण के लिए कम से कम 80 क्षेत्रीय देशी प्रजातियों का सुझाव देता है। यह मार्गदर्शन है, अनिवार्यता नहीं।",
