  "EcoCrop lists a killing temperature above this site's record low, but the species is native to this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop nennt eine Absterbetemperatur über dem Rekordtief dieses Standorts, doch die Art ist in diesem Land heimisch. Halber Abzug statt Ausschluss; das Winterhärte-Feld ist der Verdächtige.",
  "EcoCrop lists a killing temperature above this site's record low, but Kew records the species as naturalized in this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop nennt eine Absterbetemperatur über dem Rekordtief dieses Standorts, doch Kew führt die Art als in diesem Land eingebürgert. Halber Abzug statt Ausschluss; das Winterhärte-Feld ist der Verdächtige.",
