  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "Der gemessene Oberboden hier ist {t}, außerhalb des bevorzugten Bodenartbereichs dieser Art: weicher Abzug, nie ein Ausschluss.",
