  "Annual rain here sits just above this species' EcoCrop ceiling. Excess-rain limits proxy disease and drainage rather than survival, so it takes a half penalty instead of exclusion.": "Der Jahresniederschlag liegt hier knapp über der EcoCrop-Obergrenze dieser Art. Nässe-Limits stehen für Krankheit und Drainage, nicht fürs Überleben, daher halber Abzug statt Ausschluss.",
