  "Requires at least {req} cm soil depth (EcoCrop), but this {slope}° slope supports only ~{avail} cm equilibrium soil.": "Erfordert mindestens {req} cm Bodentiefe (EcoCrop), aber dieser Hang mit {slope}° hält nur etwa {avail} cm Gleichgewichtsboden.",
