  "Native to this country, but not to this region (WCVP)": "Asili ya nchi hii, lakini si eneo hili (WCVP)",
  "Part of the native flora of this region (WCVP)": "Sehemu ya mimea asilia ya eneo hili (WCVP)",
  "{n} species recorded as invasive in this country were excluded from these recommendations ({src}).": "Spishi {n} zilizorekodiwa kuwa vamizi nchini humu zimeondolewa kwenye mapendekezo haya ({src}).",
  "No natives from our base clear the bar here. The base (FAO EcoCrop) covers cultivated species and thinly covers wild native floras, like this region's; try 'everything', or ask a local restoration nursery.": "Hakuna spishi asilia kutoka hifadhidata yetu inayofikia kiwango hapa. Msingi (FAO EcoCrop) unahusu spishi zinazolimwa na hauwakilishi vizuri mimea asilia ya porini kama ya eneo hili; jaribu 'zote', au uliza kitalu cha urejeshaji cha karibu.",
  "The record low here sits within the grid's frost margin. Reanalysis under-reports valley and highland night frosts, so this frost-tender species takes a half penalty.": "Kiwango cha chini kabisa hapa kiko ndani ya ukingo wa barafu wa gridi. Uchambuzi-upya hupunguza barafu za usiku za mabondeni na nyanda za juu, hivyo spishi hii isiyostahimili barafu inapata adhabu nusu.",
  "Part of the native flora of {region} (WCVP). Ranges resolve at whole-province scale; where a species grows within {region} varies.": "Sehemu ya mimea asilia ya {region} (WCVP). Mipaka hubainishwa kwa kiwango cha jimbo zima; mahali spishi inapoota ndani ya {region} hutofautiana.",
  "Inside this species' mapped native range (Little/USGS digitized polygons, ~50 km resolution)": "Ndani ya eneo asilia lililochorwa la spishi hii (poligoni za kidijitali za Little/USGS, azimio ~50 km)",
  "Native to this country, but its mapped range (Little/USGS) does not reach here": "Asili ya nchi hii, lakini eneo lake lililochorwa (Little/USGS) halifiki hapa",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native right here per its mapped range. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop inaonyesha joto la kuua juu ya kiwango cha chini kabisa cha eneo hili, lakini spishi ni asilia hapa hasa kwa mujibu wa eneo lililochorwa. Adhabu nusu badala ya kuondolewa; sehemu ya ustahimilivu ndiyo inayoshukiwa.",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native to this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop inaonyesha joto la kuua juu ya kiwango cha chini kabisa cha eneo hili, lakini spishi ni asilia katika nchi hii. Adhabu nusu badala ya kuondolewa; sehemu ya ustahimilivu ndiyo inayoshukiwa.",
  "EcoCrop lists a killing temperature above this site's record low, but Kew records the species as naturalized in this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop inaonyesha joto la kuua juu ya kiwango cha chini kabisa cha eneo hili, lakini Kew inarekodi spishi hii kama iliyozoea katika nchi hii. Adhabu nusu badala ya kuondolewa; sehemu ya ustahimilivu ndiyo inayoshukiwa.",
  "soil texture": "muundo wa udongo",
  "light (sandy)": "mwepesi (mchanga)",
  "medium (loamy)": "wa kati (tifutifu)",
  "heavy (clayey)": "mzito (mfinyanzi)",
  "organic (peaty)": "ogani (mboji)",
  "ISRIC SoilGrids topsoil (0-30 cm); scored softly against each species' EcoCrop texture preference": "Udongo wa juu wa ISRIC SoilGrids (0-30 cm); unapimwa kwa upole dhidi ya upendeleo wa muundo wa EcoCrop wa kila spishi",
  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "Udongo wa juu uliopimwa hapa ni {t}, nje ya safu ya muundo inayopendelewa na spishi hii: adhabu laini, kamwe si kutengwa.",
  "irrigated": "inamwagiliwa",
  "measured pH": "pH iliyopimwa",
  "measured": "imepimwa",
  "Scored as irrigated: water counts as available up to this species' optimum. Excess rain still applies.": "Imepimwa kwa umwagiliaji: maji yanahesabiwa kuwa yanapatikana hadi kiwango bora cha spishi hii. Mvua kupita kiasi bado inahesabika.",
  "Annual rain here sits just above this species' EcoCrop ceiling. Excess-rain limits proxy disease and drainage rather than survival, so it takes a half penalty instead of exclusion.": "Mvua ya mwaka hapa iko juu kidogo ya kikomo cha EcoCrop cha spishi hii. Vikomo vya mvua kupita kiasi vinaashiria magonjwa na mifereji, si kuishi, hivyo adhabu nusu badala ya kuondolewa.",
  "wetland": "ardhioevu",
  "on slope": "kwenye mteremko",
  "Needs standing water or saturated soil year-round (EcoCrop drainage)": "Inahitaji maji yaliyotuama au udongo uliolowa mwaka mzima (mifereji ya EcoCrop)",
  "This is a wetland species (needs saturated soil or standing water), and this point sits on a {n}° slope.": "Hii ni spishi ya ardhioevu (inahitaji udongo uliolowa au maji yaliyotuama), na eneo hili liko kwenye mteremko wa {n}°.",
  "Requires at least {req} cm soil depth (EcoCrop), but this {slope}° slope supports only ~{avail} cm equilibrium soil.": "Inahitaji kina cha udongo cha angalau cm {req} (EcoCrop), lakini mteremko huu wa {slope}° unashikilia takriban cm {avail} tu za udongo.",
  "Did something look wrong? Send feedback": "Kuna kitu si sahihi? Tuma maoni",
