  "up to {n} seedlings": "{n} fidana kadar",
  "for planting on your own property": "kendi arazinize dikim için",
  "fast-growing": "hızlı büyüyen",
  "slow-growing": "yavaş büyüyen",
  "What would grow in that empty lot down your street?": "Sokağınızdaki o boş arsada ne yetişirdi?",
  "or draw an area yourself": "veya kendiniz bir alan çizin",
  "Public land? You can plant, just tell the city first and follow the local urban forestry plan. Private land? Talk to the owner before anything.": "Kamu arazisi mi? Dikim yapabilirsiniz, sadece önce belediyeye bildirin ve yerel kentsel ormancılık planına uyun. Özel mülk mü? Her şeyden önce mülk sahibiyle görüşün.",
  "vacant lot": "boş arsa",
  "open land": "açık alan",
  "meadow": "çayır",
  "Part of the native flora of this region (WCVP)": "Bu bölgenin yerel florasının bir parçası (WCVP)",
  "{n} species recorded as invasive in this country were excluded from these recommendations ({src}).": "Bu ülkede istilacı olarak kaydedilen {n} tür bu önerilerden hariç tutuldu ({src}).",
  "No natives from our base clear the bar here. The base (FAO EcoCrop) covers cultivated species and thinly covers wild native floras, like this region's; try 'everything', or ask a local restoration nursery.": "Veritabanımızdaki yerli türlerden hiçbiri buradaki kriterleri karşılamadı. Tabanımız (FAO EcoCrop) ağırlıklı olarak kültür türlerini kapsar ve bu bölge gibi yabani floraları sınırlı içerir; 'hepsi' seçeneğini deneyin veya yerel bir fidanlığa danışın.",
  "The record low here sits within the grid's frost margin. Reanalysis under-reports valley and highland night frosts, so this frost-tender species takes a half penalty.": "Buradaki rekor düşük sıcaklık, ızgaranın don sınırında kalıyor. Yeniden analiz vadi ve yayla gece donlarını eksik bildirdiğinden, dona hassas bu türe yarım ceza puanı uygulanır.",
  "Part of the native flora of {region} (WCVP). Ranges resolve at whole-province scale; where a species grows within {region} varies.": "{region} yerel florasının bir parçası (WCVP). Dağılımlar il/bölge ölçeğinde çözümlenir; türün {region} içindeki tam yayılışı değişiklik gösterebilir.",
  "Inside this species' mapped native range (Little/USGS digitized polygons, ~50 km resolution)": "Bu türün haritalanmış yerel yayılış alanı içinde (Little/USGS sayısallaştırılmış poligonları, ~50 km çözünürlük)",
  "Native to this country, but its mapped range (Little/USGS) does not reach here": "Bu ülkeye özgü yerli tür, ancak haritalanmış yayılış alanı (Little/USGS) buraya kadar uzanmıyor",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native right here per its mapped range. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop bu saha için öldürücü sıcaklığı rekor düşük sıcaklığın üzerinde listeliyor, ancak tür haritalanmış yayılışına göre tam burada yerlidir. Hariç tutulmak yerine yarım ceza verildi; dayanıklılık verisi şüphelidir.",
  "EcoCrop lists a killing temperature above this site's record low, but the species is native to this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop bu saha için öldürücü sıcaklığı rekor düşük sıcaklığın üzerinde listeliyor, ancak tür bu ülkede yerlidir. Hariç tutulmak yerine yarım ceza verildi; dayanıklılık verisi şüphelidir.",
  "EcoCrop lists a killing temperature above this site's record low, but Kew records the species as naturalized in this country. Penalized half instead of excluded; the hardiness field is the suspect.": "EcoCrop bu saha için öldürücü sıcaklığı rekor düşük sıcaklığın üzerinde listeliyor, ancak Kew türü bu ülkede doğallaşmış olarak kaydediyor. Hariç tutulmak yerine yarım ceza verildi; dayanıklılık verisi şüphelidir.",
  "soil texture": "toprak dokusu",
  "light (sandy)": "hafif (kumlu)",
  "medium (loamy)": "orta (tınlı)",
  "heavy (clayey)": "ağır (killi)",
  "organic (peaty)": "organik (turbalı)",
  "ISRIC SoilGrids topsoil (0-30 cm); scored softly against each species' EcoCrop texture preference": "ISRIC SoilGrids üst toprak (0-30 cm); her türün EcoCrop doku tercihine göre yumuşak puanlanır",
  "The measured topsoil here is {t}, outside this species' preferred texture range: soft penalty, never an exclusion.": "Buradaki ölçülen üst toprak {t}, bu türün tercih ettiği doku aralığının dışında: yumuşak ceza, asla eleme değil.",
  "irrigated": "sulanıyor",
  "measured pH": "ölçülen pH",
  "measured": "ölçülü",
  "Scored as irrigated: water counts as available up to this species' optimum. Excess rain still applies.": "Sulamalı olarak puanlandı: su, bu türün optimumuna kadar mevcut sayılır. Aşırı yağış sınırı yine geçerlidir.",
  "Annual rain here sits just above this species' EcoCrop ceiling. Excess-rain limits proxy disease and drainage rather than survival, so it takes a half penalty instead of exclusion.": "Buradaki yıllık yağış bu türün EcoCrop üst sınırının hemen üzerinde. Aşırı yağış sınırları hayatta kalmayı değil hastalık ve drenajı yansıtır, bu yüzden hariç tutulmak yerine yarım ceza verilir.",
