  "This is a wetland species (needs saturated soil or standing water), and this point sits on a {n}° slope.": "Bu bir sulak alan türü (suya doymuş toprak veya durgun su ister) ve bu nokta {n}° eğimli bir yamaçta.",
  "Requires at least {req} cm soil depth (EcoCrop), but this {slope}° slope supports only ~{avail} cm equilibrium soil.": "En az {req} cm toprak derinliği ister (EcoCrop), ancak bu {slope}° eğimli yamaç yalnızca ~{avail} cm denge toprağını tutabilir.",
  "Did something look wrong? Send feedback": "Bir şey mi yanlış görünüyor? Geri bildirim gönder",
